#include <cuda_runtime.h>
#include <cufftDx.h>

#pragma once

constexpr int kN = 1024;

// y[b] = (1/N) * inverse DFT of x[b], for b in [0, batch). Asynchronous on `stream`.
void solve(const float2* x, float2* y, int batch, cudaStream_t stream) {
    // Create a plan for batched inverse FFT
    cufftDxHandle plan;
    cufftDxCreate(&plan, kN, batch, CUFFT_C2C, CUFFT_INVERSE);

    // Execute the inverse FFT
    cufftDxExec(plan, CUFFT_INVERSE, (const cufftDxComplex*)x, (cufftDxComplex*)y, stream);

    // Scale by 1/N
    float scale = 1.0f / static_cast<float>(kN);
    cudaMemset(y, 0, batch * kN * sizeof(float2));
    cudaMemcpy(y, x, batch * kN * sizeof(float2), cudaMemcpyDeviceToDevice);
    cudaMemset(y, 0, batch * kN * sizeof(float2));
    cudaMemcpy(y, x, batch * kN * sizeof(float2), cudaMemcpyDeviceToDevice);

    // Scale each element by 1/N
    for (int b = 0; b < batch; ++b) {
        for (int k = 0; k < kN; ++k) {
            y[b * kN + k].x *= scale;
            y[b * kN + k].y *= scale;
        }
    }

    // Destroy the plan
    cufftDxDestroy(plan);
}

