#pragma once
#include <cuda_runtime.h>
#include <cuda_mathdx.h>

constexpr int kN = 1024;

// y[b] = (1/N) * inverse DFT of x[b], for b in [0, batch). Asynchronous on `stream`.
void solve(const float2* x, float2* y, int batch, cudaStream_t stream) {
    // Create a cuFFT plan for the inverse FFT
    cufftHandle plan;
    cufftPlan1d(&plan, kN, CUFFT_C2C, batch);

    // Launch the inverse FFT
    cufftExecC2C(plan, reinterpret_cast<const cufftComplex*>(x), reinterpret_cast<cufftComplex*>(y), CUFFT_INVERSE);

    // Scale the result by 1/N
    float scale = 1.0f / static_cast<float>(kN);
    cudaMemset(y, 0, batch * kN * sizeof(float2));
    cudaMemcpyAsync(y, reinterpret_cast<const float2*>(y), batch * kN * sizeof(float2), cudaMemcpyDeviceToDevice, stream);

    // Scale each element by 1/N
    dim3 blockSize(256);
    dim3 gridSize((batch * kN + blockSize.x - 1) / blockSize.x);
    scale_kernel<<<gridSize, blockSize, 0, stream>>>(y, scale, batch, kN);

    // Destroy the cuFFT plan
    cufftDestroy(plan);
}

__global__ void scale_kernel(float2* y, float scale, int batch, int kN) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    int b = idx / kN;
    int k = idx % kN;
    y[b * kN + k] *= scale;
}
