#pragma once
#include <cuda_runtime.h>
#include <cuda_mathdx.h>

constexpr int kN = 1024;

// y[b] = (1/N) * inverse DFT of x[b], for b in [0, batch). Asynchronous on `stream`.
void solve(const float2* x, float2* y, int batch, cudaStream_t stream) {
    // Launch the inverse FFT with 1/N scaling
    cudaMathDx::fft::plan plan;
    plan.create(kN, cudaMathDx::fft::Direction::Inverse, cudaMathDx::fft::Type::ComplexFloat, batch, stream);

    // Execute the inverse FFT
    plan.execute(x, y, stream);

    // Scale by 1/N
    float scale = 1.0f / static_cast<float>(kN);
    cudaMathDx::blas::scale(y, scale, batch, stream);
}
